        cov_sum.compute_root()
               .split(i, io, ii, tile_i)
               .split(j, jo, jj, tile_j)
               // Within a tile, iterate ii (contiguous dim) innermost, then jj.
               .reorder(ii, jj, io, jo);

        // Reduction update:
        cov_sum.update()
               .split(i, io, ii, tile_i)
               .split(j, jo, jj, tile_j)
               .split(r_samples, ro, ri, tile_k)
               // Loop order:
               //   for io, for jo:
               //     for ro (sample tiles):
               //       for ri (samples within tile):
               //         for jj, for ii (contiguous in ii, vectorized)
               .reorder(ii, jj, ri, ro, io, jo)
               .parallel(io)            // different i-tiles are independent
               .vectorize(ii, vec_width);
    }

    // Final scaling: covariance(i,j) = cov_sum(i,j) / (float_n - 1).
    // This is a simple pointwise transform over an MxM matrix. We tile the
    // matrix, parallelize over tiles, and vectorize across contiguous i.
    {
