    // Layout: data_param(j, i) = data[i][j] (j = feature, i = sample)
    ImageParam data_param(type_of<num_t>(), 2, "data_param");

    // Scalar parameter float_n and its reciprocals.
    Param<num_t> float_n_param("float_n_param");
    Param<num_t> inv_float_n_param("inv_float_n_param");
    Param<num_t> inv_float_n_minus1_param("inv_float_n_minus1_param");

