        .update()
        // Tile the feature dimension into chunks of tile_j.
        .split(j, j_outer_mean, j_inner_mean, tile_j)
        // Inside each update, process features in contiguous inner loops
        // for better cache behavior and vectorization:
        //   r_rows (samples) outer, then j tiles (outer), then j_inner (inner).
        .reorder(j_inner_mean, r_rows, j_outer_mean)
        // Parallelize across feature tiles; each tile updates a disjoint
        // subset of mean_sum[] for all samples.
        .parallel(j_outer_mean)
        // Vectorize across contiguous features inside each tile.
        .vectorize(j_inner_mean, vec_width);

    // Means are small (size M) and read-only afterwards, so just compute at root.
    mean.compute_root();

