    // We block i, j, and k:
    //   i = io * tile_i + ii
    //   j = jo * tile_j + jj
    //   k = ko * tile_k + ki
    //
    // Loop order in the update:
    //   for ko:
    //     for jo:
    //       for io in parallel:
    //         for ki:
    //           for jj (vectorized):
